import type { Metadata } from 'next';

// Public origin of the site, used for canonical URLs, sitemap and Open Graph.
export const SITE_URL = (process.env.NEXT_PUBLIC_SITE_URL || 'https://smuzzie.com').replace(/\/$/, '');

export const SITE_NAME = 'Smuzzie';

// Generated by src/app/opengraph-image.tsx
const OG_IMAGE = '/opengraph-image';

/**
 * Per-page metadata with canonical + Open Graph/Twitter tags.
 * Child `openGraph` replaces the root one entirely in Next.js, so it has to be set per page.
 */
export function pageMetadata({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  const fullTitle = `${title} | ${SITE_NAME}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title: fullTitle,
      description,
      url: path,
      siteName: SITE_NAME,
      type: 'website',
      images: [{ url: OG_IMAGE, width: 1200, height: 630 }],
    },
    twitter: { card: 'summary_large_image', title: fullTitle, description, images: [OG_IMAGE] },
  };
}
